#include "../reader_gesture.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace manga;TouchPair p;assert(p.update(17,0,100,200));assert(p.update(255,0,220,200));assert(p.count()==2&&p.mixed);assert(!p.update(0,0,300,300));PinchAnchor a;a.start(p,1,0,100,320,240,320,640);float scale=1,x=0,y=100;p.update(17,1,40,200);p.update(255,1,280,200);a.apply(p,320,240,320,640,scale,x,y);assert(scale==2);assert(std::abs((160+x)/scale-a.content_x)<.01f);assert(std::abs((200+y)/scale-a.content_y)<.01f);p.update(255,2,280,200);assert(p.count()==1&&p.mixed&&p.remaining().id==17);p.update(17,3,40,200);assert(p.count()==0);p.reset();assert(!p.mixed);p.update(0,0,150,200);p.update(1,0,170,200);a.start(p,1,0,0,320,240,320,640);p.update(0,1,-10000,-10000);p.update(1,1,10000,10000);a.apply(p,320,240,320,640,scale,x,y);assert(scale==4&&x>=0&&y>=0&&x<=960&&y<=2320);p.update(0,1,160,200);p.update(1,1,160,200);a.apply(p,320,240,320,640,scale,x,y);assert(scale==.375f&&x==0&&y==0);std::cout<<"Two-pointer IDs, third-pointer rejection, anchor preservation, limits and cancellation passed\n";}
